{-| @Backend.Runtime.Kernel.Natural — unsigned integers as 32-bit limbs for the signature
    checks. -}
module Pudu.Backend.Runtime.Kernel.Natural (naturalKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
naturalKernelParts :: [(Text, [Text], [Text])]
naturalKernelParts =
  [ ("nat_load", [],
      [ "/* Big-endian bytes as count limbs, least significant first. The answer says"
      , "   whether every byte past the limbs is zero, so the value fits. */"
      , "static int pudu_nat_load(const unsigned char *bytes, size_t length, uint32_t *limbs, size_t count) {"
      , "  int fits = 1;"
      , "  for (size_t i = 0; i < count; ++i) limbs[i] = 0;"
      , "  for (size_t i = 0; i < length; ++i) {"
      , "    size_t place = length - 1 - i;"
      , "    if (place / 4 < count) limbs[place / 4] |= (uint32_t)bytes[i] << (8 * (place % 4));"
      , "    else if (bytes[i] != 0) fits = 0;"
      , "  }"
      , "  return fits;"
      , "}"
      ])
  , ("nat_compare", [],
      [ "static int pudu_nat_compare(const uint32_t *a, const uint32_t *b, size_t count) {"
      , "  for (size_t i = count; i-- > 0;) if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;"
      , "  return 0;"
      , "}"
      ])
  , ("nat_mul", [],
      [ "/* out, of a_count + b_count limbs, is a times b. */"
      , "static void pudu_nat_mul(const uint32_t *a, size_t a_count, const uint32_t *b, size_t b_count, uint32_t *out) {"
      , "  for (size_t i = 0; i < a_count + b_count; ++i) out[i] = 0;"
      , "  for (size_t i = 0; i < a_count; ++i) {"
      , "    uint64_t carry = 0;"
      , "    for (size_t j = 0; j < b_count; ++j) {"
      , "      carry += (uint64_t)a[i] * b[j] + out[i + j];"
      , "      out[i + j] = (uint32_t)carry;"
      , "      carry >>= 32;"
      , "    }"
      , "    out[i + b_count] = (uint32_t)carry;"
      , "  }"
      , "}"
      ])
  , ("nat_rem", [],
      [ "/* rest, of count limbs, is the value modulo the divisor, whose top limb is"
      , "   not zero. Long division a limb at a time on shifted copies; work holds"
      , "   value_count + count + 1 limbs. */"
      , "static void pudu_nat_rem(const uint32_t *value, size_t value_count, const uint32_t *divisor, size_t count, uint32_t *rest, uint32_t *work) {"
      , "  uint32_t *u = work, *v = work + value_count + 1;"
      , "  int shift = 0;"
      , "  if (value_count < count) {"
      , "    for (size_t i = 0; i < count; ++i) rest[i] = i < value_count ? value[i] : 0;"
      , "    return;"
      , "  }"
      , "  if (count == 1) {"
      , "    uint64_t held = 0;"
      , "    for (size_t i = value_count; i-- > 0;) held = ((held << 32) | value[i]) % divisor[0];"
      , "    rest[0] = (uint32_t)held;"
      , "    return;"
      , "  }"
      , "  while (((divisor[count - 1] << shift) & UINT32_C(0x80000000)) == 0) shift += 1;"
      , "  for (size_t i = count; i-- > 0;)"
      , "    v[i] = (divisor[i] << shift) | (shift != 0 && i != 0 ? divisor[i - 1] >> (32 - shift) : 0);"
      , "  u[value_count] = shift != 0 ? value[value_count - 1] >> (32 - shift) : 0;"
      , "  for (size_t i = value_count; i-- > 0;)"
      , "    u[i] = (value[i] << shift) | (shift != 0 && i != 0 ? value[i - 1] >> (32 - shift) : 0);"
      , "  for (size_t j = value_count - count + 1; j-- > 0;) {"
      , "    uint64_t top = ((uint64_t)u[j + count] << 32) | u[j + count - 1];"
      , "    uint64_t guess = top / v[count - 1], left = top % v[count - 1], carry = 0, taken;"
      , "    uint32_t borrow = 0;"
      , "    while (guess > UINT32_MAX || guess * v[count - 2] > ((left << 32) | u[j + count - 2])) {"
      , "      guess -= 1;"
      , "      left += v[count - 1];"
      , "      if (left > UINT32_MAX) break;"
      , "    }"
      , "    for (size_t i = 0; i < count; ++i) {"
      , "      carry += guess * v[i];"
      , "      taken = (uint64_t)u[i + j] - (uint32_t)carry - borrow;"
      , "      u[i + j] = (uint32_t)taken;"
      , "      borrow = (uint32_t)(taken >> 32) & 1;"
      , "      carry >>= 32;"
      , "    }"
      , "    taken = (uint64_t)u[j + count] - carry - borrow;"
      , "    u[j + count] = (uint32_t)taken;"
      , "    if (((taken >> 32) & 1) != 0) {"
      , "      carry = 0;"
      , "      for (size_t i = 0; i < count; ++i) {"
      , "        carry += (uint64_t)u[i + j] + v[i];"
      , "        u[i + j] = (uint32_t)carry;"
      , "        carry >>= 32;"
      , "      }"
      , "      u[j + count] += (uint32_t)carry;"
      , "    }"
      , "  }"
      , "  for (size_t i = 0; i < count; ++i)"
      , "    rest[i] = (u[i] >> shift) | (shift != 0 ? u[i + 1] << (32 - shift) : 0);"
      , "}"
      ])
  ]
